INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('signup', '{"enabled":true}', 'Public sign-up: new businesses can open their own account and start a plan', NULL, '2026-10-25T10:18:33.477Z', '2026-10-25T10:18:33.477Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('store_domains', '{"main_site":"store","root_domain":null}', 'Store addresses: root domain for store subdomains (needs wildcard DNS) and what the platform address shows (marketing or the default store)', NULL, '2026-10-25T10:18:33.501Z', '2026-10-25T10:18:33.501Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('courier_panel', '{"connected":false,"providers":{}}', 'Courier sign-in accounts (Steadfast, Pathao, RedX, Carrybee, Paperfly): accounts per courier and their last test', NULL, '2026-10-25T10:18:33.618Z', '2026-10-25T10:18:33.618Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('onboarding', '{"method":"online_payment","reminder_days":[3,1],"whatsapp_number":null,"whatsapp_template":"Hello Fullfilio, I have just signed up and would like my account activated.\nBusiness: {business}\nName: {name}\nMobile: {phone}\nE-mail: {email}\nPlan: {plan} ({price} / {interval})"}', 'How new businesses are activated (online payment or WhatsApp) and when expiry reminders go out', NULL, '2026-10-25T10:18:33.698Z', '2026-10-25T10:18:33.698Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('billing_controls', '{"pricing":{"SMS":{"max":100000,"min":100,"enabled":true,"presets":[500,1000,5000,10000],"unit_poisha":36},"BALANCE":{"max_tk":50000,"min_tk":100,"enabled":true,"presets":[200,500,1000,5000]},"COURIER":{"max":20000,"min":50,"enabled":false,"presets":[100,500,1000],"unit_poisha":100}},"purposes":{"SMS":true,"BALANCE":true,"COURIER":true,"SUBSCRIPTION":true},"max_payment_tk":100000}', 'Online payments to the platform: what can be bought, prices per credit and limits', NULL, '2026-10-25T10:18:33.818Z', '2026-10-25T10:18:33.818Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('billing_gateways', '{"bkash":{"enabled":false,"sandbox":true},"paystation":{"enabled":false,"sandbox":true},"sslcommerz":{"enabled":false,"sandbox":true}}', 'Gateways merchants use to pay invoices and buy credits (platform accounts)', NULL, '2026-10-25T10:18:33.271Z', '2026-10-25T10:18:33.977Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('signup_offer', '{"enabled":false,"trial_days":2,"first_price":99,"first_periods":1}', 'New businesses: free trial days, then the first period(s) at an introductory price, then the plan price', NULL, '2026-10-25T10:18:33.982Z', '2026-10-25T10:18:33.982Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('access_rules', '{"ACTIVE":"FULL","PAUSED":"READ_ONLY","EXPIRED":"BLOCKED","PAST_DUE":"FULL","TRIALING":"FULL","CANCELLED":"READ_ONLY","TRIAL_ENDED":"BLOCKED","NO_SUBSCRIPTION":"FULL","MERCHANT_SUSPENDED":"BLOCKED","MERCHANT_ONBOARDING":"FULL","PAST_DUE_AFTER_GRACE":"READ_ONLY"}', 'What each account state allows: FULL, READ_ONLY (look but not change; customers can still order) or BLOCKED (no admin, no new orders)', NULL, '2026-10-25T10:18:33.191Z', '2026-10-25T10:18:33.982Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('email_service', '{"enabled":false,"from_name":"","from_email":"","daily_limit":300}', 'Fullfilio email service (Resend): sender address and the daily limit per store. The API key lives in Vault (email.resend).', NULL, '2026-10-25T10:18:34.065Z', '2026-10-25T10:18:34.065Z');
